CREATE OR REPLACE FUNCTION public._workspace_event_display(_source_kind text,_outcome text,_capability text)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER
CALLED ON NULL INPUT PARALLEL UNSAFE COST 100 SET search_path=pg_catalog,public
AS $e2_display$
DECLARE result jsonb;
BEGIN
 result:=public._workspace_event_display_before_e04_effectuation(_source_kind,_outcome,_capability);
 IF _source_kind='capability_run' AND _capability='sales_effectuate_commercial_terms' THEN
  result:=result||pg_catalog.jsonb_build_object('actor_type','owner_staff',
   'title',CASE WHEN _outcome='capability_succeeded' THEN 'Signed commercial terms made effective' ELSE 'Commercial terms not made effective' END,
   'summary',CASE WHEN _outcome='capability_succeeded' THEN 'An owner or admin approved the matching signed commercial terms. No payment or completed service is confirmed.' ELSE 'The action did not complete. Refresh the current commercial record.' END);
 END IF;
 IF _source_kind='capability_run' AND _outcome='capability_succeeded' THEN
  CASE _capability
   WHEN 'agreement_list' THEN
    result:=result||pg_catalog.jsonb_build_object('title','Read agreement records',
     'summary','Existing agreements were looked up. No agreement was sent, signed or changed.');
   WHEN 'agreement_status' THEN
    result:=result||pg_catalog.jsonb_build_object('title','Read agreement status',
     'summary','The recorded status was checked. No agreement was approved, sent or signed.');
   WHEN 'find_clients_for_status' THEN
    result:=result||pg_catalog.jsonb_build_object('title','Looked up client records',
     'summary','Existing clients were searched for a status lookup. No business records were changed.');
   ELSE NULL;
  END CASE;
 END IF;
 RETURN result;
END $e2_display$;
COMMIT;
